WITH metrics AS (SELECT *, NTILE(5) OVER (PARTITION BY event_type ORDER BY duration_sec DESC, id) AS duration_sec_bucket, SUM(duration_sec) OVER (PARTITION BY event_type ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_duration_sec, SUM(duration_sec) OVER (PARTITION BY page ORDER BY duration_sec, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_duration_sec_2, AVG(duration_sec) OVER (PARTITION BY page ORDER BY duration_sec, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) AS duration_sec_avg_5 FROM web_events) SELECT CASE WHEN cumulative_duration_sec >= 2378 THEN 'LARGE' ELSE 'SMALL' END AS cumulative_duration_sec_tier, CASE WHEN duration_sec >= 465 THEN 'PREMIUM' ELSE 'STANDARD' END AS duration_sec_tier, (UNIX_TIMESTAMP(MAX(event_time)) - UNIX_TIMESTAMP(MIN(event_time))) / 60 AS duration_min, SUM(duration_sec_bucket) AS total_duration_sec_bucket, GROUPING(CASE WHEN cumulative_duration_sec >= 2378 THEN 'LARGE' ELSE 'SMALL' END) AS gid FROM metrics GROUP BY CUBE (CASE WHEN cumulative_duration_sec >= 2378 THEN 'LARGE' ELSE 'SMALL' END, CASE WHEN duration_sec >= 465 THEN 'PREMIUM' ELSE 'STANDARD' END) ORDER BY duration_sec_tier;
